# Block 1259, across Eastern Parkway from the site, Franklin Avenue to
# Bedford Avenue: its lots, dissolved into one outline.
return curio_load_data("data.nyc.crown-heights-1550-bedford", part="block-1259.geojson")

{
  "map": {
    "layerRefs": [
      {
        "dataRef": "[!! input_0 !!]",
