      },
      {
        "dataRef": "[!! input_4 !!]",
        "color": "#d5d9df",
        "stroke": false,
        "title": "Streets"
      },
      {
        "dataRef": "[!! input_2 !!]",
        "selectFields": [
          "building_id"
        ],
        "getFnv": "status",
