        "colorMapInterpolator": "schemeTableau10",
        "title": "Building"
      },
      {
        "dataRef": "[!! input_1 !!]",
        "isPick": true,
        "getFnv": "shadow_shown",
        "getFnvType": "quantitative",
        "isColorMap": true,
        "colorMapInterpolator": "interpolateRdPu",
        "stroke": false,
        "opacity": 0.9,
        "title": "Accumulated shadow (hours)"
      },
      {
        "dataRef": "[!! input_3 !!]",
        "color": "#ffd166",
